input.script:
listing = boundary retry 3 {
    first = list_tickets({ page: 1, status: "open" })
    rest = for p in list.range(2, first.total_pages + 1) {
        r = boundary retry 3 { return list_tickets({ page: p, status: "open" }) } catch err {
            return fail("LIST", err.message)
        }
        return r.items
    }
    items = fold acc = first.items for page_items in rest { return acc + page_items }
    return items
} catch err {
    return fail("LIST_ALL", err.message)
}

cutoff_ms = time.parse("2026-06-03T00:00:00Z")

candidates = for t in listing {
    created = time.parse(t.created_at)
    skip if created >= cutoff_ms
    return t
}

escalated = for t in candidates {
    detail = boundary retry 3 { return get_ticket({ id: t.id }) } catch err {
        return fail("GET", err.message)
    }
    body = detail.body if detail.body != null else ""
    skip if not ("refund" in text.lower(body))
    updated = boundary retry 3 {
        return update_ticket({ id: t.id, priority: "high", add_tags: ["billing-escalation"] })
    } catch err {
        return fail("UPDATE", err.message)
    }
    return t.id
}

sorted = list.sort(escalated)
submitted = submit_result({ answer: { escalated_ticket_ids: sorted } })
return { escalated_ticket_ids: sorted, recorded: submitted.recorded }
